from xgcm import Grid  # noqa: E402
from xgcm.padding import pad  # noqa: E402


def face_connections() -> dict[
    str, dict[int, dict[str, tuple[tuple[object, ...], ...]]]
]:
    """Return the documented cubed-sphere connectivity used by the case."""
    return {
        "face": {
            0: {
                "X": ((3, "X", False), (1, "X", False)),
                "Y": ((4, "Y", False), (5, "Y", False)),
            },
            1: {
                "X": ((0, "X", False), (2, "X", False)),
                "Y": ((4, "X", False), (5, "X", True)),
            },
            2: {
                "X": ((1, "X", False), (3, "X", False)),
                "Y": ((4, "Y", True), (5, "Y", True)),
            },
            3: {
                "X": ((2, "X", False), (0, "X", False)),
                "Y": ((4, "X", True), (5, "X", False)),
            },
            4: {
                "X": ((3, "Y", True), (1, "Y", False)),
                "Y": ((2, "Y", True), (0, "Y", False)),
            },
            5: {
                "X": ((3, "Y", False), (1, "Y", True)),
                "Y": ((0, "Y", False), (2, "Y", True)),
            },
        }
    }


def make_case(n: int) -> tuple[xr.DataArray, Grid]:
    """Build a coordinate-free field whose value identifies its source face."""
    connections = face_connections()
    face_count = len(connections["face"])
    values = np.broadcast_to(
        np.arange(face_count, dtype=float)[:, None, None],
        (face_count, n, n),
    ).copy()
    dataset = xr.Dataset(
        {"grid_field": (("face", "y", "x"), np.zeros_like(values))},
        coords={
            "x": (("x",), np.arange(n), {"axis": "X"}),
            "xl": (
                ("xl",),
                np.arange(n) - 0.5,
                {"axis": "X", "c_grid_axis_shift": -0.5},
            ),
            "y": (("y",), np.arange(n), {"axis": "Y"}),
            "yl": (
                ("yl",),
                np.arange(n) - 0.5,
                {"axis": "Y", "c_grid_axis_shift": -0.5},
            ),
            "face": (("face",), np.arange(face_count)),
        },
    )
    grid = Grid(dataset, face_connections=connections)
    tracer = xr.DataArray(values, dims=("face", "y", "x"))
    return tracer, grid


def padded_result(data: xr.DataArray, grid: Grid) -> xr.DataArray:
    return pad(
        data,
        grid,
        {"X": (1, 1), "Y": (1, 1)},
        boundary={"X": "fill", "Y": "fill"},
        fill_value=-1.0,
    )


def edge_values(
    values: np.ndarray, target_face: int, axis: str, side: str
) -> np.ndarray:
    if axis == "X":
        index = 0 if side == "left" else -1
        return values[target_face, 1:-1, index]
    index = 0 if side == "left" else -1
    return values[target_face, index, 1:-1]


def inspect_probe(
    values: np.ndarray,
    probe: dict[str, object],
    connections: dict[str, dict[int, dict[str, tuple[tuple[object, ...], ...]]]],
) -> dict[str, object]:
    target_face = int(probe["target_face"])
    axis = str(probe["axis"])
    side = str(probe["side"])
    if axis not in {"X", "Y"} or side not in {"left", "right"}:
        raise ValueError("edge probe has an invalid axis or side")

    side_index = 0 if side == "left" else 1
    connection = connections["face"][target_face][axis][side_index]
    source_face = int(connection[0])
    observed = edge_values(values, target_face, axis, side)
    declared_neighbor = np.full(observed.shape, source_face, dtype=float)
    return {
        "target_face": target_face,
        "axis": axis,
        "side": side,
        "declared_neighbor_face": source_face,
        "observed_values_in_input_layout": [float(value) for value in observed],
        "matches_declared_neighbor": bool(np.array_equal(observed, declared_neighbor)),
    }


def run_workflow(n: int, probes: list[dict[str, object]]) -> dict[str, object]:
    tracer, grid = make_case(n)
    alternate_tracer = tracer.transpose("face", "x", "y")
    primary_result = padded_result(tracer, grid)
    alternate_result = padded_result(alternate_tracer, grid)
    primary = np.asarray(primary_result.values, dtype=float)
    primary_canonical = np.asarray(
        primary_result.transpose("face", "y", "x").values,
        dtype=float,
    )
    alternate_canonical = np.asarray(
        alternate_result.transpose("face", "y", "x").values,
        dtype=float,
    )
    if not (
        np.isfinite(primary).all()
        and np.isfinite(primary_canonical).all()
        and np.isfinite(alternate_canonical).all()
    ):
        raise ArithmeticError("connected-grid workflow produced non-finite values")

    connections = face_connections()
    edge_observations = [inspect_probe(primary, probe, connections) for probe in probes]
    dimension_order_preserved = primary_result.dims == tracer.dims
    connected_edges_match = bool(
        edge_observations
        and all(item["matches_declared_neighbor"] for item in edge_observations)
    )
    same_shape = primary_canonical.shape == alternate_canonical.shape
    representation_difference = (
        float(np.max(np.abs(primary_canonical - alternate_canonical)))
        if same_shape and primary_canonical.size
        else None
    )
    return {
        "input_dimension_order": list(tracer.dims),
        "returned_dimension_order": list(primary_result.dims),
        "dimension_order_preserved": dimension_order_preserved,
        "canonical_shape": list(primary_canonical.shape),
        "connected_edge_observations": edge_observations,
        "connected_edges_match_in_input_layout": connected_edges_match,
        "connected_grid_contract_holds": bool(
            dimension_order_preserved and connected_edges_match
        ),
        "representation_observation": {
            "input_dimension_orders": [
                list(tracer.dims),
                list(alternate_tracer.dims),
            ],
            "same_canonical_shape": same_shape,
            "max_abs_difference": representation_difference,
            "exact_match": bool(
                same_shape
                and representation_difference is not None
                and representation_difference == 0.0
            ),
            "authoritative": False,
        },
    }


def reject_nonfinite_constant(value: str) -> None:
    raise ValueError(f"non-finite JSON constant is not allowed: {value}")


def main() -> int:
    if len(sys.argv) != 2:
        raise SystemExit("usage: cubed_sphere_case.py FIXTURE")
    fixture = json.loads(
        Path(sys.argv[1]).read_text(encoding="utf-8"),
        parse_constant=reject_nonfinite_constant,
    )
    payload = run_workflow(int(fixture["n"]), list(fixture["edge_probes"]))
    print(json.dumps(payload, sort_keys=True, allow_nan=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
